cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and empty policy ---
  it.todo("quotes an empty item list as premium 5 G (processing fee only)");

  // --- Quote: base premiums per main item type (price list catalogue) ---
  it.todo("quotes a single plain sword (base 100 G) for a 0-year customer as premium 116 G (100 + 10 first insurance + 5 fee, rounded up from 115)");
  it.todo("quotes a single plain amulet (base 60 G) for a 0-year customer as premium 71 G (60 + 6 first insurance + 5 fee)");
  it.todo("quotes a single plain staff (base 80 G) for a 0-year customer as premium 93 G (80 + 8 first insurance + 5 fee)");
  it.todo("quotes a single plain potion (base 40 G) for a 0-year customer as premium 49 G (40 + 4 first insurance + 5 fee)");

  // --- Quote: component base premiums and the building block of 3 alike ---
  it.todo("quotes 1 rune (base 25 G) as component base premium 25 G");
  it.todo("quotes 1 moonstone (base 25 G) as component base premium 25 G");
  it.todo("quotes 2 runes as base premium 50 G (no block)");
  it.todo("quotes 3 runes as base premium 60 G (block applies)");
  it.todo("quotes 4 runes as base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes as base premium 175 G (no block -- block requires exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone as base premium 75 G (no block: alike means same type)");
  it.todo("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks, one per type)");
  it.todo("quotes 3 moonstones as base premium 60 G (block applies to moonstones too)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to the cursed item's base premium (cursed sword adds 50 G)");
  it.todo("adds a 30 % high-enchantment surcharge for enchantment exactly 5 (sword adds 30 G)");
  it.todo("adds no high-enchantment surcharge for enchantment 4 (sword adds 0 G)");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment exactly 5");
  it.todo("applies the curse surcharge only to the cursed item, not the policy total: cursed sword + plain amulet -> base 160 G, curse adds 50 G -> 210 G before policy modifiers and fee");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies the 20 % loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies the 10 % first-insurance surcharge on the policy base premium of every quote");
  it.todo("applies a 15 % follow-up-contract discount to the customer's second quote in the scenario");
  it.todo("applies no follow-up-contract discount to the customer's first quote");
  it.todo("adds the 5 G processing fee at the very end of the premium calculation");

  // --- Quote: rounding in MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G (rounding in the MHPCO's favour)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) as premium 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed steel sword (enchantment 7) as premium 160 G");

  // --- Quote: rejection ---
  it.todo("rejects a quote containing an item of unknown type (e.g. broomstick): CLI exits non-zero, writes an error description to stderr, and writes no results to stdout");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays out 400 G for a regular steel sword (enchantment 3) with 500 G damage (full reimbursement minus 100 G deductible)");
  it.todo("pays out 100 G for a damaged rune (insurance value 250 G) with 200 G damage (no enchantment or material, so no special clause)");
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G in one incident -> payout 600 G");

  // --- Claim: special clauses ---
  it.todo("reimburses damage to an item with enchantment >= 8 at 50 %: steel sword enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("fully reimburses damage to a dragon-material item: dragon sword enchantment 5, damage 800 G -> payout 700 G");
  it.todo("lets the 50 % rule win when both clauses apply: dragon sword enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("applies the high-enchantment clause at exactly enchantment 8: dragon sword, damage 1000 G -> payout 400 G");

  // --- Claim: cap ---
  it.todo("caps the payout at twice the insurance sum: sword (sum 1000 G, cap 2000 G), first claim of 1500 G -> payout 1400 G, remainingCap 600 G");
  it.todo("reduces a later claim to the remaining cap: second claim of 1500 G on the same sword policy -> payout 600 G, remainingCap 0 G");
  it.todo("derives the insurance sum from all covered items: sword + amulet -> sum 1600 G, cap 3200 G");
  it.todo("bases the cap on unmodified insurance values: cursed sword (premium 165 G with modifiers) -> cap 2000 G");
  it.todo("excludes the block discount from the insurance sum: sword + 3 runes -> sum 1750 G, cap 3500 G");

  // --- Claim: multiple items of the same type ---
  it.todo("insures two swords as insurance sum 2000 G with cap 4000 G");
  it.todo("treats each of two sword damage entries as a separate damage with its own deductible when two swords are insured");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured): CLI exits non-zero with an error description on stderr");

  // --- Claim: rounding and rejection ---
  it.todo("rounds a payout of 350.5 G down to 350 G (rounding in the MHPCO's favour)");
  it.todo("rejects a claim referencing an item not part of the policy (amulet damaged, only a sword insured): CLI exits non-zero with an error description on stderr");
  it.todo("rejects a claim referencing a damaged item of unknown type: CLI exits non-zero with an error description on stderr");
  it.todo("rejects a claim containing a damage entry with amount -200: CLI exits non-zero with an error description on stderr");

  // --- CLI end-to-end ---
  it.todo("reads a scenario from stdin and writes a results array of the same length and order to stdout");
  it.todo("returns premium for quote results and payout plus remainingCap for claim results, as integers");
  it.todo("resolves a claim's zero-based policy step index to the policy created by that earlier quote step");
});
EOF
