p='src/claim-office.ts'
s=open(p).read()
s=s.replace('''const COMPONENT_TYPES''','''const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;

const COMPONENT_TYPES''')
s += '''
export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Policy {
  items: Item[];
  remainingCap: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

function insuranceValueOf(type: string): number {
  const value = INSURANCE_VALUES[type];
  if (value === undefined) {
    throw new Error(`MHPCO does not insure items of type "${type}"`);
  }
  return value;
}

export function openPolicy(items: Item[]): Policy {
  const insuranceSum = items.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
  return { items, remainingCap: insuranceSum * CAP_FACTOR };
}

function reimbursementFor(damage: Damage): number {
  return Math.max(0, damage.amount - DEDUCTIBLE);
}

export function claim(policy: Policy, incident: Incident): ClaimResult {
  const desired = incident.damages.reduce((sum, damage) => sum + reimbursementFor(damage), 0);
  const payout = Math.floor(Math.min(desired, policy.remainingCap));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}
'''
