import { claim, openPolicy, quote } from "./claim-office.js";
import type { Customer, Incident, Item, Policy } from "./claim-office.js";

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

type Step = QuoteStep | ClaimStep;

interface Scenario {
  customer: Customer;
  steps: Step[];
}

type StepResult = { premium: number } | { payout: number; remainingCap: number };

function readStdin(): Promise<string> {
  return new Promise((resolve, reject) => {
    let input = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (chunk) => (input += chunk));
    process.stdin.on("end", () => resolve(input));
    process.stdin.on("error", reject);
  });
}

function policyFor(policies: Map<number, Policy>, step: ClaimStep): Policy {
  const policy = policies.get(step.policy);
  if (policy === undefined) {
    throw new Error(`Step ${step.policy} did not create a policy`);
  }
  return policy;
}

function runScenario(scenario: Scenario): StepResult[] {
  const policies = new Map<number, Policy>();
  let contracts = 0;
  return scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      const premium = quote(scenario.customer, step.items, contracts);
      contracts += 1;
      policies.set(index, openPolicy(step.items));
      return { premium };
    }
    return claim(policyFor(policies, step), step.incident);
  });
}

async function main(): Promise<void> {
  const scenario = JSON.parse(await readStdin()) as Scenario;
  process.stdout.write(JSON.stringify({ results: runScenario(scenario) }));
}

main().catch((error: unknown) => {
  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
  process.exitCode = 1;
});
EOF
